-- Smart Restaurant Supply, Demand & Food Waste Optimization System
-- MySQL 8.0+ | Run this file once in MySQL Workbench or mysql CLI.
CREATE DATABASE IF NOT EXISTS restaurant_optimization CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE restaurant_optimization;

CREATE TABLE IF NOT EXISTS Users (User_ID INT AUTO_INCREMENT PRIMARY KEY,Name VARCHAR(100) NOT NULL,Role ENUM('Admin','Manager','Staff') NOT NULL DEFAULT 'Staff',Email VARCHAR(100) UNIQUE NOT NULL,Phone VARCHAR(15),Password_Hash VARCHAR(255) NOT NULL,Created_At TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Supplier (Supplier_ID INT AUTO_INCREMENT PRIMARY KEY,Name VARCHAR(100) NOT NULL,Contact_No VARCHAR(15),Email VARCHAR(100),Address VARCHAR(255));
CREATE TABLE IF NOT EXISTS Ingredient (Ingredient_ID INT AUTO_INCREMENT PRIMARY KEY,Name VARCHAR(100) NOT NULL,Category VARCHAR(50),Unit VARCHAR(20) NOT NULL,Cost_Per_Unit DECIMAL(10,2) NOT NULL DEFAULT 0 CHECK(Cost_Per_Unit>=0),Reorder_Level DECIMAL(10,2) NOT NULL DEFAULT 0 CHECK(Reorder_Level>=0));
CREATE TABLE IF NOT EXISTS Purchase_Order (PO_ID INT AUTO_INCREMENT PRIMARY KEY,Supplier_ID INT NOT NULL,Order_Date DATE NOT NULL,Status ENUM('Pending','Delivered','Cancelled') DEFAULT 'Pending',Total_Amount DECIMAL(12,2) DEFAULT 0,Created_By INT,FOREIGN KEY(Supplier_ID) REFERENCES Supplier(Supplier_ID) ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY(Created_By) REFERENCES Users(User_ID) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS Purchase_Item (PO_ID INT NOT NULL,Ingredient_ID INT NOT NULL,Quantity DECIMAL(10,2) NOT NULL CHECK(Quantity>0),Unit_Price DECIMAL(10,2) NOT NULL CHECK(Unit_Price>=0),PRIMARY KEY(PO_ID,Ingredient_ID),FOREIGN KEY(PO_ID) REFERENCES Purchase_Order(PO_ID) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY(Ingredient_ID) REFERENCES Ingredient(Ingredient_ID) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS Stock_Batch (Batch_ID INT AUTO_INCREMENT PRIMARY KEY,Ingredient_ID INT NOT NULL,Quantity DECIMAL(10,2) NOT NULL CHECK(Quantity>=0),Expiry_Date DATE,Received_Date DATE NOT NULL,FOREIGN KEY(Ingredient_ID) REFERENCES Ingredient(Ingredient_ID) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS Dish (Dish_ID INT AUTO_INCREMENT PRIMARY KEY,Dish_Name VARCHAR(100) NOT NULL,Category VARCHAR(50),Price DECIMAL(10,2) NOT NULL CHECK(Price>=0));
CREATE TABLE IF NOT EXISTS Recipe (Dish_ID INT NOT NULL,Ingredient_ID INT NOT NULL,Qty_Required DECIMAL(10,3) NOT NULL CHECK(Qty_Required>0),PRIMARY KEY(Dish_ID,Ingredient_ID),FOREIGN KEY(Dish_ID) REFERENCES Dish(Dish_ID) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY(Ingredient_ID) REFERENCES Ingredient(Ingredient_ID) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS Customer_Order (Order_ID INT AUTO_INCREMENT PRIMARY KEY,Order_Date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,Order_Type ENUM('Dine-In','Takeaway','Delivery') DEFAULT 'Dine-In',Total_Amount DECIMAL(12,2) DEFAULT 0,Handled_By INT,FOREIGN KEY(Handled_By) REFERENCES Users(User_ID) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS Order_Item (Order_ID INT NOT NULL,Dish_ID INT NOT NULL,Quantity INT NOT NULL CHECK(Quantity>0),Item_Price DECIMAL(10,2) NOT NULL CHECK(Item_Price>=0),PRIMARY KEY(Order_ID,Dish_ID),FOREIGN KEY(Order_ID) REFERENCES Customer_Order(Order_ID) ON DELETE CASCADE ON UPDATE CASCADE,FOREIGN KEY(Dish_ID) REFERENCES Dish(Dish_ID) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS Food_Waste (Waste_ID INT AUTO_INCREMENT PRIMARY KEY,Ingredient_ID INT NOT NULL,Quantity DECIMAL(10,2) NOT NULL CHECK(Quantity>0),Reason ENUM('Expired','Spoiled','Over-Preparation','Plate Waste','Other') NOT NULL,Waste_Date DATE NOT NULL,Recorded_By INT,FOREIGN KEY(Ingredient_ID) REFERENCES Ingredient(Ingredient_ID) ON DELETE RESTRICT ON UPDATE CASCADE,FOREIGN KEY(Recorded_By) REFERENCES Users(User_ID) ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS Alert (Alert_ID INT AUTO_INCREMENT PRIMARY KEY,Ingredient_ID INT NOT NULL,Alert_Type ENUM('Low Stock','Overstock','Near Expiry') NOT NULL,Alert_Date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,Status ENUM('Active','Resolved') DEFAULT 'Active',FOREIGN KEY(Ingredient_ID) REFERENCES Ingredient(Ingredient_ID) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX idx_ingredient_name ON Ingredient(Name);
CREATE INDEX idx_batch_expiry ON Stock_Batch(Expiry_Date);
CREATE INDEX idx_batch_ingredient ON Stock_Batch(Ingredient_ID,Quantity);
CREATE INDEX idx_order_date ON Customer_Order(Order_Date);
CREATE INDEX idx_waste_date ON Food_Waste(Waste_Date);
CREATE INDEX idx_alert_status ON Alert(Status);

CREATE OR REPLACE VIEW v_ingredient_stock AS SELECT i.Ingredient_ID,i.Name,i.Unit,i.Reorder_Level,COALESCE(SUM(b.Quantity),0) Available FROM Ingredient i LEFT JOIN Stock_Batch b ON b.Ingredient_ID=i.Ingredient_ID GROUP BY i.Ingredient_ID,i.Name,i.Unit,i.Reorder_Level;
CREATE OR REPLACE VIEW v_monthly_waste AS SELECT DATE_FORMAT(Waste_Date,'%Y-%m') Waste_Month,Reason,SUM(Quantity) Total_Quantity,COUNT(*) Records FROM Food_Waste GROUP BY DATE_FORMAT(Waste_Date,'%Y-%m'),Reason;

DELIMITER $$
CREATE TRIGGER trg_stock_batch_alert AFTER INSERT ON Stock_Batch FOR EACH ROW BEGIN DECLARE current_stock DECIMAL(12,2); DECLARE reorder DECIMAL(12,2); SELECT COALESCE(SUM(Quantity),0) INTO current_stock FROM Stock_Batch WHERE Ingredient_ID=NEW.Ingredient_ID; SELECT Reorder_Level INTO reorder FROM Ingredient WHERE Ingredient_ID=NEW.Ingredient_ID; IF current_stock<reorder THEN IF NOT EXISTS(SELECT 1 FROM Alert WHERE Ingredient_ID=NEW.Ingredient_ID AND Alert_Type='Low Stock' AND Status='Active') THEN INSERT INTO Alert(Ingredient_ID,Alert_Type) VALUES(NEW.Ingredient_ID,'Low Stock'); END IF; END IF; END$$
CREATE TRIGGER trg_stock_batch_alert_update AFTER UPDATE ON Stock_Batch FOR EACH ROW BEGIN DECLARE current_stock DECIMAL(12,2); DECLARE reorder DECIMAL(12,2); SELECT COALESCE(SUM(Quantity),0) INTO current_stock FROM Stock_Batch WHERE Ingredient_ID=NEW.Ingredient_ID; SELECT Reorder_Level INTO reorder FROM Ingredient WHERE Ingredient_ID=NEW.Ingredient_ID; IF current_stock<reorder THEN IF NOT EXISTS(SELECT 1 FROM Alert WHERE Ingredient_ID=NEW.Ingredient_ID AND Alert_Type='Low Stock' AND Status='Active') THEN INSERT INTO Alert(Ingredient_ID,Alert_Type) VALUES(NEW.Ingredient_ID,'Low Stock'); END IF; END IF; END$$
CREATE PROCEDURE sp_low_stock() BEGIN SELECT * FROM v_ingredient_stock WHERE Available<Reorder_Level ORDER BY Available ASC; END$$
CREATE PROCEDURE sp_generate_expiry_alerts() BEGIN INSERT INTO Alert(Ingredient_ID,Alert_Type) SELECT DISTINCT Ingredient_ID,'Near Expiry' FROM Stock_Batch WHERE Expiry_Date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 3 DAY) AND Quantity>0 AND NOT EXISTS(SELECT 1 FROM Alert a WHERE a.Ingredient_ID=Stock_Batch.Ingredient_ID AND a.Alert_Type='Near Expiry' AND a.Status='Active'); END$$
DELIMITER ;
